export function makeRulesDispatcher(world, getActorId, opts = {}) {
  const _onAction = typeof opts.onAction === "function" ? opts.onAction : null;
  const uiTarget = /** @type {any} */ ((typeof window !== "undefined") ? window : globalThis);
