  return function dispatch(action) {
    // Display-side lock: used for brief blocking FX windows (e.g. thrown-item flight).
    if (typeof window !== "undefined") {
      try {
        if (/** @type {any} */ (window).__JSHACK_INPUT_LOCKED === true) return;
        if (
