      }
      case "rules.wait": {
        world?.add?.(actorId, WaitIntent, {});
        world?.tick?.(1);
        break;
      }
      case "rules.search": {
        world?.add?.(actorId, SearchIntent, {});
        world?.tick?.(1);
        break;
      }
      case "rules.cyclePosture": {
        world?.add?.(actorId, SetPostureIntent, { mode: "cycle" });
